---@class MonthSignManager
MonthSignManager = class("MonthSignManager")
function MonthSignManager:Get()
    if self._instance == nil then
        self._instance = MonthSignManager()
    end
    return self._instance
end
function MonthSignManager:initialize()
    ---@type table<number,MonthSignData>
    self.monthSignList={}
    self.validCount = 0
    self.monthSignedNum = 0
end

---@param msg SC_UserMonthSign
function MonthSignManager:OnInit(msg)
    self.validCount = #msg.mySignInfo
    self.curMonth=msg.monthNum
    self.monthSignedNum = 0
    self.monthCardExp = msg.monthCardExp
    for i = 1, self.validCount do
        local data = self.monthSignList[msg.mySignInfo[i].dayNum]
        if data == nil then
            data = MonthSignData()
            self.monthSignList[msg.mySignInfo[i].dayNum] = data
        end
        data:SetData(msg.mySignInfo[i])
        if data.receive then
            self.monthSignedNum = self.monthSignedNum+1
        end
    end
    --UINotify:Get():SendNotification(UINotifyEvent.MonthSignListDataRefresh)
    UINotify:Get():SendNotification(UINotifyEvent.WelfareVideoOpenPage, WelfareFuncType.monthSign)
    UINotify:Get():SendNotification(UINotifyEvent.WelfareVideo_PageRunAction, { WelfareFuncType.monthSign, "RefreshMonthSignScrollView" })
end
---@param msg SC_UserSignInfo
function MonthSignManager:UpdateData(msg)
    local data = self.monthSignList[msg.dayNum]
    self.monthSignedNum=self.monthSignedNum+1
    data:SetData(msg)
    --UINotify:Get():SendNotification(UINotifyEvent.MonthSignListDataRefresh)
    UINotify:Get():SendNotification(UINotifyEvent.WelfareVideo_PageRunAction, { WelfareFuncType.monthSign, "RefreshMonthSignScrollView" })

end

